import{_ as p,r as n,o,c as l,e as s,a as c,s as i}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"布局 - October CMS - 3.x","titleTemplate":false,"description":"为您的网站页面定义脚手架。","frontmatter":{"subtitle":"为您的网站页面定义脚手架。"},"headers":[{"level":2,"title":"使用动态页面标题","slug":"使用动态页面标题","link":"#使用动态页面标题","children":[]},{"level":2,"title":"占位符","slug":"占位符","link":"#占位符","children":[]},{"level":2,"title":"动态布局","slug":"动态布局","link":"#动态布局","children":[{"level":3,"title":"布局执行生命周期","slug":"布局执行生命周期","link":"#布局执行生命周期","children":[]},{"level":3,"title":"方法和变量访问","slug":"方法和变量访问","link":"#方法和变量访问","children":[]},{"level":3,"title":"优先布局","slug":"优先布局","link":"#优先布局","children":[{"level":4,"title":"另请参阅","slug":"另请参阅","link":"#另请参阅","children":[]}]}]}],"relativePath":"3.x/zh-cn/cms/themes/layouts.md","filePath":"3.x/zh-cn/cms/themes/layouts.md"}'),u={name:"3.x/zh-cn/cms/themes/layouts.md"};function g(k,a,d,r,h,m){const t=n("pre-heading"),e=n("post-heading");return o(),l("div",null,[s(t),a[0]||(a[0]=c("h1",null,"布局",-1)),s(e),a[1]||(a[1]=i(`<p>布局为您的页面定义了一个通用的脚手架，通常意味着在每个页面上重复出现的所有内容，例如页头和页脚。它们几乎总是包含 HTML 代码，如 HEAD、TITLE 和 BODY 标签。</p><p>布局模板文件位于主题中的 <strong>layouts</strong> 目录中。布局模板文件应具有 <strong>htm</strong> 扩展名。在布局文件中，您应该使用 <code>{% page %}</code> 标签来输出页面内容。以下是最简单的布局示例。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>html</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span>
        <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">page</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>html</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><div class="custom-block aside"><p>请记住，如果您引用子目录中的布局，则应指定子目录名称。</p></div><p>要为<a href="./pages.html">页面</a>使用布局，页面应在配置部分中引用布局文件名（不带扩展名）。下面是使用 <strong>default.htm</strong> 布局的页面模板示例。</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/</span>&quot;</span>
<span class="token key attr-name">layout</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">default</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>Hello, world!<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><p>当请求此页面时，其内容会与布局合并，更准确地说 - 布局的 <code>{% page %}</code> 标签会被页面内容替换。前面的示例将生成以下标记：</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>html</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>Hello, world!<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>html</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>请注意，您可以在布局中<a href="./partials.html">渲染部件</a>。这使您可以在不同的布局之间共享通用的标记元素。例如，您可以有一个输出网站 CSS 和 JavaScript 链接的部件。这种方法简化了资源管理 - 如果您想添加 JavaScript 引用，只需修改一个部件而不是编辑所有布局。</p><p>配置部分对于布局是可选的。支持的配置参数是 <strong>name</strong> 和 <strong>description</strong>。这些参数是可选的，用于后端用户界面。带有描述的布局模板示例：</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">description</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Basic layout example</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>html</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span>
        <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">page</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>html</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><h2 id="使用动态页面标题"><a href="#使用动态页面标题" class="header-anchor">#</a> 使用动态页面标题</h2><p><a href="./pages.html">页面</a>的 <code>meta_title</code> 和 <code>meta_description</code> 属性支持从页面生命周期中解析变量。以下布局模板将根据活动页面的值设置页面标题。</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>html</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>head</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>title</span><span class="token punctuation">&gt;</span></span>{{ this.page.meta_title }} - October CMS<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>title</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>head</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span>
        {% page %}
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>html</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>页面模板可以使用类似 Twig 的变量语法来定义其标题，使用全局环境中可用的值，在此情况下使用 <strong>post.title</strong> 值。</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog</span>&quot;</span>
<span class="token key attr-name">meta_title</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">{{ post.title }} - Blog</span>&quot;</span>
</code></pre></div><blockquote><p><strong>注意</strong>：仅支持基本的 Twig 变量。不能使用过滤器、标签和函数。</p></blockquote><h2 id="占位符"><a href="#占位符" class="header-anchor">#</a> 占位符</h2><p>占位符允许页面向布局注入内容。占位符在布局模板中使用 <code>{% placeholder %}</code> 标签定义。下一个示例显示了在 HTML HEAD 部分中定义了 <strong>head</strong> 占位符的布局模板。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>html</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>head</span><span class="token punctuation">&gt;</span></span>
        <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">placeholder</span> head <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>head</span><span class="token punctuation">&gt;</span></span>
    ...
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>html</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>页面可以使用 <code>{% put %}</code> 和 <code>{% endput %}</code> 标签向占位符注入内容。以下示例演示了一个简单的页面模板，它将 CSS 链接注入到前面示例中定义的 <strong>head</strong> 占位符。</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/my-page</span>&quot;</span>
<span class="token key attr-name">layout</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">default</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">put</span> head <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>link</span> <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>/themes/demo/assets/css/page.css<span class="token punctuation">&quot;</span></span> <span class="token attr-name">rel</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>stylesheet<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endput</span> <span class="token delimiter punctuation">%}</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>The page content goes here.<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><p>有关占位符的更多信息可以在<a href="./../markup/tag-placeholder.html">标记指南</a>中找到。</p><h2 id="动态布局"><a href="#动态布局" class="header-anchor">#</a> 动态布局</h2><p>布局与页面一样，可以使用任何 Twig 功能。有关详细信息，请参阅文档的<a href="./pages.html">动态页面部分</a>。</p><h3 id="布局执行生命周期"><a href="#布局执行生命周期" class="header-anchor">#</a> 布局执行生命周期</h3><p>在布局的 PHP 代码部分中，您可以定义以下用于处理页面执行生命周期的函数：<code>onInit</code>、<code>onStart</code>、<code>onBeforePageStart</code> 和 <code>onEnd</code>。</p><p><code>onInit</code> 函数在所有组件初始化后和处理 AJAX 请求之前执行。<code>onStart</code> 函数在页面处理开始时执行。<code>onBeforePageStart</code> 函数在布局<a href="./components.html">组件</a>运行之后但在页面的 <code>onStart</code> 函数执行之前执行。<code>onEnd</code> 函数在页面渲染之后执行。处理程序的执行顺序如下：</p><ol><li>布局 <code>onInit()</code> 函数。</li><li>页面 <code>onInit()</code> 函数。</li><li>布局 <code>onStart()</code> 函数。</li><li>布局组件 <code>onRun()</code> 方法。</li><li>布局 <code>onBeforePageStart()</code> 函数。</li><li>页面 <code>onStart()</code> 函数。</li><li>页面组件 <code>onRun()</code> 方法。</li><li>页面 <code>onEnd()</code> 函数。</li><li>布局 <code>onEnd()</code> 函数。</li></ol><h3 id="方法和变量访问"><a href="#方法和变量访问" class="header-anchor">#</a> 方法和变量访问</h3><p>在部件、页面和布局内部访问变量和方法时，使用最近的上下文。以下是 <a href="./themes.html">PHP 代码部分</a>的定义。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onStart</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;myVariable&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token keyword">function</span> <span class="token function-definition function">myMethod</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token string single-quoted-string">&#39;bar&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>在上面的示例中，在 Twig 中访问 <code>myVariable</code> 或 <code>this.myMethod()</code> 将按以下顺序检查存在性：</p><ol><li>部件</li><li>页面</li><li>布局</li></ol><h3 id="优先布局"><a href="#优先布局" class="header-anchor">#</a> 优先布局</h3><p>布局可以在其设置中指定 <code>is_priority</code> 属性以激活优先模式。在正常情况下，布局内容在页面内容之后渲染。这允许页面操作布局属性，如标题或元描述。从视觉上看，顺序如下。</p><div class="language-text extra-class"><pre class="language-text"><code>Layout (3) ← Page (1) → Partials (2)
</code></pre></div><p>在优先模式下，布局使用更自然的加载顺序，其中 <code>{% page %}</code> 标签与布局内容内联渲染。但是，在使用此模式时不支持占位符。优先布局的加载顺序更像这样。</p><div class="language-text extra-class"><pre class="language-text"><code>Layout (1) → Page (2) → Partials (3)
</code></pre></div><p>这在<a href="./../resources/building-apis.html">构建 API 端点</a>时特别有用。在以下示例中，由于从未调用 page 标签，页面逻辑将不会运行。</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">description</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">API Layout</span>&quot;</span>
<span class="token key attr-name">is_priority</span> <span class="token punctuation">=</span> <span class="token value attr-value">1</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> <span class="token boolean">false</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">page</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><h4 id="另请参阅"><a href="#另请参阅" class="header-anchor">#</a> 另请参阅</h4><div class="custom-block also"><ul><li><a href="./../../markup/tag/page.html">Page Twig 标签</a></li></ul></div>`,43))])}const w=p(u,[["render",g]]);export{y as __pageData,w as default};
